import re
import csv
import io
from xml.sax.saxutils import unescape


def _clean_text(s):
    if s is None:
        return ""
    s = s.replace("&#x2003;", " ")
    s = re.sub(r"<[^>]+>", "", s)
    s = unescape(s)
    s = s.replace("\u2003", " ")
    s = s.strip()
    s = re.sub(r"\s+", " ", s)
    return s


def _extract_rows(xml_str):
    rows = []
    for row_match in re.finditer(r"<row[^>]*>(.*?)</row>", xml_str, re.DOTALL):
        row_content = row_match.group(1)
        entries = re.findall(r"<entry[^>]*?(?:/>|>(.*?)</entry>)", row_content, re.DOTALL)
        cells = [_clean_text(e) for e in entries]
        rows.append(cells)
    return rows


def _parse_conc_to_nm(header_text):
    # returns float nM or None
    m = re.search(r"([\d.]+)\s*(u|n|m)?M", header_text, re.IGNORECASE)
    if not m:
        return None
    val = float(m.group(1))
    unit = (m.group(2) or "").lower()
    if unit == "u":
        return val * 1000.0
    elif unit == "m":
        return val * 1000000.0
    elif unit == "n":
        return val
    else:
        return val


def _is_compound_id(s):
    s2 = s.strip().replace("*", "")
    s2 = re.sub(r"^ISIS\s*", "", s2, flags=re.IGNORECASE)
    return bool(re.fullmatch(r"\d{4,7}", s2))


def _clean_compound_id(s):
    s2 = s.strip()
    s2 = re.sub(r"^ISIS\s*", "", s2, flags=re.IGNORECASE)
    s2 = re.sub(r"[^\d]", "", s2)
    return s2


def _is_sequence(s):
    if not s:
        return False
    s2 = s.strip().upper()
    atgc_count = sum(1 for c in s2 if c in "ATGC")
    non_atgc_alpha = sum(1 for c in s2 if c.isalpha() and c not in "ATGC")
    if atgc_count >= 8 and non_atgc_alpha == 0:
        return True
    return False


def _looks_like_sugar_motif(s):
    if not s:
        return False
    s2 = s.strip()
    if not s2:
        return False
    return bool(re.fullmatch(r"[a-zA-Z0-9\-]+", s2)) and any(c.isalpha() for c in s2) and not _is_sequence(s2)


def _looks_like_backbone_motif(s):
    if not s:
        return False
    s2 = s.strip()
    if not s2:
        return False
    return bool(re.fullmatch(r"[so\-]+", s2, re.IGNORECASE)) and len(s2) >= 3


def _find_header_rows(rows, data_row_indices):
    # header candidate rows are non-empty rows before the first data row block start
    if not data_row_indices:
        return []
    first_data_idx = data_row_indices[0]
    header_rows = []
    for i in range(first_data_idx):
        r = rows[i]
        if r and any(c.strip() for c in r):
            header_rows.append((i, r))
    return header_rows


def _get_max_cols(rows, indices):
    m = 0
    for i in indices:
        m = max(m, len(rows[i]))
    return m


def xml_to_csv(xml_str: str) -> str:
    rows = _extract_rows(xml_str)

    # Identify data rows: rows whose first cell looks like a compound id
    data_indices = []
    for i, r in enumerate(rows):
        if not r:
            continue
        first = r[0].strip() if r[0] else ""
        if _is_compound_id(first):
            data_indices.append(i)

    output = io.StringIO()
    writer = csv.writer(output, delimiter=",", quoting=csv.QUOTE_MINIMAL, lineterminator="\n")
    writer.writerow(["Compound ID", "sequence", "sugar_motif", "backbone_motif",
                      "dosage_nm", "Inhibition_pct", "measurement_note"])

    if not data_indices:
        return output.getvalue()

    max_cols = _get_max_cols(rows, data_indices)

    header_rows = _find_header_rows(rows, data_indices)

    # Build aligned header grid: right-align header rows against max_cols
    # We'll build a column-header-text list, combining header row cells per column
    col_headers = ["" for _ in range(max_cols)]

    for _, hrow in header_rows:
        n = len(hrow)
        offset = max_cols - n
        if offset < 0:
            offset = 0
        for j, cell in enumerate(hrow):
            col_idx = j + offset
            if col_idx < max_cols and cell.strip():
                if col_headers[col_idx]:
                    col_headers[col_idx] += " " + cell.strip()
                else:
                    col_headers[col_idx] = cell.strip()

    # Determine column roles
    seq_col = None
    sugar_col = None
    backbone_col = None
    inhibition_col = None
    is_utc = False
    dose_cols = {}  # col_idx -> nM value

    combined_header_text = " ".join(col_headers).lower()

    # detect sequence column using data rows
    sample_rows = [rows[i] for i in data_indices]

    col_seq_votes = [0] * max_cols
    col_sugar_votes = [0] * max_cols
    col_backbone_votes = [0] * max_cols

    for r in sample_rows:
        n = len(r)
        offset = max_cols - n
        if offset < 0:
            offset = 0
        for j, cell in enumerate(r):
            col_idx = j + offset
            if col_idx >= max_cols:
                continue
            if _is_sequence(cell):
                col_seq_votes[col_idx] += 1
            elif _looks_like_backbone_motif(cell):
                col_backbone_votes[col_idx] += 1
            elif _looks_like_sugar_motif(cell):
                col_sugar_votes[col_idx] += 1

    if any(col_seq_votes):
        seq_col = col_seq_votes.index(max(col_seq_votes))
        if col_seq_votes[seq_col] == 0:
            seq_col = None

    if any(col_backbone_votes):
        bc = col_backbone_votes.index(max(col_backbone_votes))
        if col_backbone_votes[bc] > 0:
            backbone_col = bc

    if any(col_sugar_votes):
        sc = col_sugar_votes.index(max(col_sugar_votes))
        if col_sugar_votes[sc] > 0 and sc != backbone_col:
            sugar_col = sc

    # detect dose-response columns via header containing uM/nM/mM
    for j, htext in enumerate(col_headers):
        if re.search(r"\d\s*(u|n|m)?M\b", htext, re.IGNORECASE):
            nm_val = _parse_conc_to_nm(htext)
            if nm_val is not None:
                dose_cols[j] = nm_val

    # detect UTC / inhibition in header
    if "utc" in combined_header_text or "% control" in combined_header_text or "percent control" in combined_header_text:
        is_utc = True
    if "inhibition" in combined_header_text:
        is_utc = False

    # find single inhibition/UTC column (non-dose-response case)
    if not dose_cols:
        for j, htext in enumerate(col_headers):
            ht = htext.lower()
            if "utc" in ht or "control" in ht:
                inhibition_col = j
                is_utc = True
                break
            if "inhibit" in ht:
                inhibition_col = j
                is_utc = False
                break
        if inhibition_col is None:
            # fallback: numeric column that's not seq/sugar/backbone and not compound id (col 0)
            for j in range(max_cols):
                if j == 0 or j == seq_col or j == sugar_col or j == backbone_col:
                    continue
                ht = col_headers[j].lower()
                if "seq id" in ht or "site" in ht or "id no" in ht:
                    continue
                # check if data numeric
                numeric_count = 0
                for r in sample_rows:
                    n = len(r)
                    offset = max_cols - n
                    if offset < 0:
                        offset = 0
                    col_idx = j
                    data_j = col_idx - offset
                    if 0 <= data_j < n:
                        val = r[data_j].strip()
                        if re.fullmatch(r"[\d.]+", val):
                            numeric_count += 1
                if numeric_count > 0:
                    inhibition_col = j

    def get_cell(r, col_idx):
        n = len(r)
        offset = max_cols - n
        if offset < 0:
            offset = 0
        data_j = col_idx - offset
        if 0 <= data_j < n:
            return r[data_j].strip()
        return ""

    for idx in data_indices:
        r = rows[idx]
        compound_raw = get_cell(r, 0)
        compound_id = _clean_compound_id(compound_raw)
        if not re.fullmatch(r"\d{4,7}", compound_id):
            continue

        seq_val = "NA"
        if seq_col is not None:
            sv = get_cell(r, seq_col)
            sv_upper = sv.strip().upper()
            atgc_count = sum(1 for c in sv_upper if c in "ATGC")
            if atgc_count >= 8:
                seq_val = sv_upper
            else:
                seq_val = "NA"

        sugar_val = "NA"
        if sugar_col is not None:
            sgv = get_cell(r, sugar_col)
            sugar_val = sgv if sgv else "NA"

        backbone_val = "NA"
        if backbone_col is not None:
            bbv = get_cell(r, backbone_col)
            backbone_val = bbv if bbv else "NA"

        if dose_cols:
            for col_idx, nm_val in dose_cols.items():
                raw_val = get_cell(r, col_idx)
                if raw_val == "" or raw_val.upper() == "N/A":
                    continue
                m = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", raw_val)
                if not m:
                    continue
                num_str = m.group(0)
                try:
                    num_val = float(num_str)
                except ValueError:
                    continue
                if is_utc:
                    inhibition_pct = 100.0 - num_val
                    note = "converted from %UTC"
                    inhibition_str = _format_number(inhibition_pct)
                else:
                    inhibition_str = num_str
                    note = "inhibition"

                dosage_str = _format_number(nm_val)

                writer.writerow([
                    compound_id,
                    seq_val,
                    sugar_val,
                    backbone_val,
                    dosage_str,
                    inhibition_str,
                    note
                ])
        else:
            if inhibition_col is None:
                continue
            raw_val = get_cell(r, inhibition_col)
            if raw_val == "" or raw_val.upper() == "N/A":
                continue
            m = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", raw_val)
            if not m:
                continue
            num_str = m.group(0)
            try:
                num_val = float(num_str)
            except ValueError:
                continue
            if is_utc:
                inhibition_pct = 100.0 - num_val
                note = "converted from %UTC"
                inhibition_str = _format_number(inhibition_pct)
            else:
                inhibition_str = num_str
                note = "inhibition"

            writer.writerow([
                compound_id,
                seq_val,
                sugar_val,
                backbone_val,
                "NA",
                inhibition_str,
                note
            ])

    return output.getvalue()


def _format_number(val):
    if val == int(val):
        return str(int(val))
    else:
        s = f"{val:.6f}".rstrip("0").rstrip(".")
        return s
